#include <bits/stdc++.h>
int main(int c, char** v) { std::mt19937 r(atoi(v[1])); int t = r() % 3 + 1; printf("%d\n", t); while (t--) { int n = r() % 6 + 2; std::vector<std::array<int,3>> e; std::vector<int> lab(n); std::iota(lab.begin(), lab.end(), 1); std::shuffle(lab.begin(), lab.end(), r); for (int i = 1; i < n; i++) e.push_back({lab[r() % i], lab[i], int(r() % 9 + 1)}); int extra = r() % 4; while (extra--) { int a = r() % n + 1, b = r() % n + 1; if (a != b) e.push_back({a, b, int(r() % 9 + 1)}); } printf("%d %d\n", n, (int)e.size()); for (auto [a, b, w] : e) printf("%d %d %d\n", a, b, w); for (int i = 0; i < n; i++) printf("%d ", int(r() % 6 + 1)); puts(""); } }
